package Controlstatement;

public class whileloop4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		
		//write a java program for counterdown timer from 10 to 1 using while loop..
		
		
		    int countertime=10;
		    
		    while(countertime>0)
		    {
		    	
		    	System.out.println("The time is : "+countertime);
		    	countertime--;
		    	//System.out.println("Time is over");
		    }
		    System.out.println("Time is over");
		    
		

	}

}
